//------------------------------------------------------------------------------
bool HasAnyICInMachine()                                                        //kevin 20150914 判斷是否還有tray在 機台
{
    for(int i=0; i<eTrayCount; i++)
    {
        if(Prod.iTrayType[i]!=tNotUse)
        {
            if(Prod.iTrayType[i]==tTrayFix)
            {
                if(MOT[iMMAuto[i]].TrayFeedHasIC())
                    return true;
            }
            else
            {
                if(MOT[iMMAuto[i]].fHasTray ||
                   MOT[iMMAuto[i]].HasIC())
                    return true;
            }
        }
    }
    return false;
}
