// ===========================================================================
//  Del_Tree  -- golden csystem.cpp:23075.  FULLY ACTIVE.
//  Recursive directory wipe.  ALSO declared by TempCtrl/TriTemp.h:116 with the
//  identical signature (`void Del_Tree(AnsiString SourceName);`, parameter name
//  differs only) and by the FROZEN csystem.h:284 -- verified that NO .cpp in the
//  port defines it (grep -rn "Del_Tree" TempCtrl/*.cpp -> 0 hits, run 20260810),
//  so this is the single definition and neither declaration carries a default
//  argument.
//  KenHsieh\'s 20230105 `&` (not `==`) attribute test is golden\'s own fix and is
//  reproduced as-is.
// ===========================================================================
void Del_Tree(AnsiString Dir)
{
    AnsiString d=Dir;
    AnsiString FileName;
    TSearchRec SearchRec;

    if(!DirectoryExists(Dir))
        return;

    if(d.SubString(d.Length(),1)!="\\")
        d=d+"\\";

    if(FindFirst(d+"*.*", faAnyFile, SearchRec) == 0)
    {
        do
        {
            if((SearchRec.Attr & faDirectory)!=0)                               //KenHsieh 20230105 : "==" => "&" 排除無法將資料夾內的資料夾清除之問題
            {
                if ((SearchRec.Name!=".") && (SearchRec.Name!=".."))
                {
                    Del_Tree(d+SearchRec.Name);                                 //遞迴呼叫
                    for(int iSubRetry=0; iSubRetry<3; iSubRetry++) { if(RemoveDir(d+SearchRec.Name)) break; MySleep(100); }   //AI(W906-W188) 20261010 (NB2-1): golden 913 csystem.cpp:24270-24276 (ht9045-v899 20260630: retry, symmetric with the final RemoveDir)
                }
            }
            else
            {
                AnsiString asDelFile=d+SearchRec.Name; for(int iDelRetry=0; iDelRetry<3; iDelRetry++) { FileSetAttr(asDelFile,faArchive); if(DeleteFile(asDelFile)) break; MySleep(100); }   //AI(W906-W188) 20261010 (NB2-1): golden 913 csystem.cpp:24281-24290 (ht9045-v899 20260630: a file in use made DeleteFile fail and was skipped -> leftover folder (State Record); retry 3 x 100 ms)
//                DeleteFile(d+SearchRec.Name);   //AI(W906-W188) 20261010 (NB2-1): golden 913 csystem.cpp:24283-24290 folded into the retry loop on the line above
            }
        }
        while(FindNext(SearchRec)==0);

        FindClose(SearchRec);
    }

    for(int iRmRetry=0; iRmRetry<3; iRmRetry++) { if(RemoveDir(d)) break; MySleep(100); }   //AI(W906-W188) 20261010 (NB2-1): golden 913 csystem.cpp:24298-24304 (ht9045-v899 20260630)
}
