TQPF_Timer MoveDelay;                                                           // golden uteach.cpp:5345
bool VerifyMotorAction()                                                        //Steven 20230728 : 確認馬達有沒有在動
{
    bool bDoorClosed=false, bDelayOk=false;
    bool bHasMoveing=false;
    static bool bNeedStopMot=false;
    AnsiString asString;

    if(W906_FormFShow("fTeach", fTeach != 0 && fTeach->fShow==true) ||
       W906_FormFShow("fMotorTest", fMotorTest != 0 && fMotorTest->fShow==true))   // golden: fTeach->fShow==true || fMotorTest->fShow==true
    {
        for(int i=0; i<TOTAL_MOTOR; i++)
        {
            if(bDoorClosed==false)
            {
                int iW906Moving=-1;                                             // AI(W906-MT-E3b): -1 = not a hook-owned motor
                if((fTeach != 0 && fTeach->btnHome->Down) ||
                   (fMotorTest != 0 && fMotorTest->btnHome->Down) ||           //JerryYang 20230815 : add
                   (W906_MotorHomingHook != 0 && W906_MotorHomingHook()))       // AI(W906-MT-E3b): web HOME job == golden btnHome->Down, see banner
                {
                    bHasMoveing=true;
                    asString="*Lock by Homeing";
                }
                else if(W906_MotorMovingHook != 0 &&
                        (iW906Moving=W906_MotorMovingHook(i))>=0)               // AI(W906-MT-E3b): hook-owned (1203) motor, R2 -- see banner
                {
                    if(MOT[i].Motor!=NULL           &&                          // golden's own guard of the MotionDone arm, kept:
                       MOT[i].Motor->Enable==true   &&                          //   a disabled motor never locks the page
                       iW906Moving>0)
                    {
                        bHasMoveing=true;
                        asString.sprintf("*Lock by %s moveing", MOT[i].NumberAlias);
                    }
                }
                else if(INDEX_MOTION_CARD==0 &&                                 //Steven 20210623 : Index使用Galil
                        (MOT[i].Mot_Name==MTestY1 || MOT[i].Mot_Name==MTestZ1 ||
                         MOT[i].Mot_Name==MTestZ2 || MOT[i].Mot_Name==MTestY2))
                {
                    if(MOT[i].Motor!=NULL           &&
                       MOT[i].Motor->Enable==true)
                    {
                        MOT[i].ScanMotorStatus();
                        if(MOT[i].Led[iInposLed])
                        {
                            bHasMoveing=true;
                            asString.sprintf("*Lock by %s moveing", MOT[i].NumberAlias);
                        }
                    }
                }
                else
                {
                    if(MOT[i].Motor!=NULL           &&
                       MOT[i].Motor->Enable==true   &&
                       MOT[i].Motor->MotionDone()==false)
                    {
                        bHasMoveing=true;
                        asString.sprintf("*Lock by %s moveing", MOT[i].NumberAlias);
                    }
                }
            }
        }

        if(bHasMoveing)
        {
            bNeedStopMot=true;                                                  //For switch case type motor move such as Home()
            W906_LockAllButtonBoth(true);                                       // golden fTeach->LockAllButton(true); fMotorTest->LockAllButton(true);
            MoveDelay.SetSecAndOn(2);                                           //For non-return type move, after arrive and wait 2 sec, then reset flag.
            g_W906MotorLock.labLockVisible=true;                                // golden fTeach->labLock->Visible=true;
            g_W906MotorLock.labLockCaption=asString;                            // golden fTeach->labLock->Caption=asString;
        }
        else
        {
            g_W906MotorLock.labLockVisible=false;                               // golden fTeach->labLock->Visible=false;
        }

        if(bNeedStopMot==true)
        {
            bDoorClosed=CheckSafeDoorIsClosed();
            bDelayOk   =MoveDelay.Off();

            if(bDoorClosed==false ||                                            //Safe door is opened
               bDelayOk==true)                                                  //Delay OK
            {
                const char* why=(bDoorClosed==false) ? "VerifyMotorAction: safe door open"
                                                     : "VerifyMotorAction: 2 s without motion";
                StopAllMotor();
                if(W906_Stop1203AllHook != 0)                                   // AI(W906-MT-E3b): golden StopAllMotor cannot reach the monitor's axes
                    W906_Stop1203AllHook(why);
                bNeedStopMot=false;
                W906_LockAllButtonBoth(false);                                  // golden fTeach->LockAllButton(false); fMotorTest->LockAllButton(false);
                if(fTeach != 0)
                    fTeach->AllBtnUp();                                         //Steven 20230815 : Add for MotorTest
                if(fMotorTest != 0)
                    fMotorTest->AllBtnUp();                                     //Steven 20230815 : Add for MotorTest
                if(fMotorTest != 0)
                    fMotorTest->bSingleHome=false;
                if(W906_MotorAllBtnUpHook != 0)                                 // AI(W906-MT-E3b): the web-owned buttons / jobs (see banner)
                    W906_MotorAllBtnUpHook(why);
                g_W906MotorLock.unlockCount++;
                g_W906MotorLock.lastUnlockWhy=why;
            }
        }
    }
    return bDoorClosed;
}

