                                Buffer2.sprintf("%s_%02d,%02d,%s - Keyin Skip", Now().FormatString("yyyymmddhhmmss"), iBarCodeErrorR+1, iBarCodeErrorC+1, Buffer.c_str());  //Alick 20170104 add 多一組LOG紀錄+上時間
                                bOCRNoIC=false;
